class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> freq;
        freq.reserve(nums.size() * 2);
        freq[0] = 1;
        int prefix = 0;
        int count = 0;
        for (int x : nums) {
            prefix += x;
            auto it = freq.find(prefix - k);
            if (it != freq.end()) count += it->second;
            ++freq[prefix];
        }
        return count;
    }
};

